    def predict_score(
        self, features: torch.Tensor, items: torch.Tensor
    ) -> torch.Tensor:
        # DEBUG: Distinguish shared catalog candidates from paired items.
        # Comparing embedding ranks alone misclassifies one-dimensional
        # candidates with final features, causing broadcasting errors or
        # silently returning paired scores instead of B x K catalog scores.
        items = torch.as_tensor(
            items, dtype=torch.long, device=features.device
        )
        embeddings = self.item_emb(items)
        if items.ndim == 1:
            return torch.matmul(features, embeddings.transpose(0, 1))
        if items.shape == features.shape[:-1]:
            return (features * embeddings).sum(-1)
        if (
            items.ndim == features.ndim
            and items.shape[:-1] == features.shape[:-1]
        ):
            return (features.unsqueeze(-2) * embeddings).sum(-1)
        raise ValueError(
            f"Incompatible feature/item shapes: {tuple(features.shape)} and "
            f"{tuple(items.shape)}; expected shared candidates, paired items, "
            "or candidates per feature position"
        )
